         + (textureLod(uReflTex, uv + 2.0 * dv, lod) + textureLod(uReflTex, uv - 2.0 * dv, lod)) * 0.131
         + (textureLod(uReflTex, uv + 3.0 * dv, lod) + textureLod(uReflTex, uv - 3.0 * dv, lod)) * 0.070;
